const input=$json.body??$json;
const text=v=>v===null||v===undefined?'':String(v).trim();
const bool=v=>typeof v==='boolean'?v:['true','1','yes','on'].includes(text(v).toLowerCase());

const action=text(input.action||'list').toLowerCase();
const clinic_name=text(input.clinic_name);
const channel=text(input.channel).toLowerCase();
const adapter_name=text(input.adapter_name);
const adapter_url=text(input.adapter_url);
const credential_reference=text(input.credential_reference);
const enabled=bool(input.enabled);
const request_timeout_seconds=Number(input.request_timeout_seconds??30);
const confirm_action=bool(input.confirm_action);

let metadata=input.metadata??{};
try{if(typeof metadata==='string')metadata=JSON.parse(metadata||'{}');}catch{metadata=null;}

const actions=['upsert','enable','disable','list'];
const channels=['whatsapp','sms','email','phone','web_push','in_app'];
const errors=[];

if(!actions.includes(action))errors.push({field:'action',message:'اقدام معتبر نیست.'});
if(!clinic_name)errors.push({field:'clinic_name',message:'نام کلینیک الزامی است.'});
if(action!=='list'&&!channels.includes(channel))errors.push({field:'channel',message:'کانال معتبر نیست.'});
if(action==='upsert'&&!adapter_name)errors.push({field:'adapter_name',message:'نام Adapter الزامی است.'});
if(action==='upsert'&&!/^https?:\/\/.+/i.test(adapter_url))errors.push({field:'adapter_url',message:'آدرس Adapter معتبر نیست.'});
if(!Number.isInteger(request_timeout_seconds)||request_timeout_seconds<1||request_timeout_seconds>300){
  errors.push({field:'request_timeout_seconds',message:'Timeout باید بین 1 و 300 ثانیه باشد.'});
}
if(!metadata||Array.isArray(metadata)||typeof metadata!=='object'){
  errors.push({field:'metadata',message:'metadata باید شیء JSON باشد.'});metadata={};
}
if(action!=='list'&&confirm_action!==true){
  errors.push({field:'confirm_action',message:'تغییر Adapter باید تأیید شود.'});
}

return [{json:{
 action,clinic_name,channel,adapter_name,adapter_url,credential_reference,
 enabled,request_timeout_seconds,metadata_text:JSON.stringify(metadata),
 confirm_action,validation_status:errors.length?'invalid':'valid',errors
}}];
